/**
 * What AccountDTO promises about itself, checked here as a courtesy.
 *
 * The server enforces these when the row is written - that is what
 * makes them true. This is so a form can say what is wrong before
 * the request, in the domain's own words.
 *
 * @returns the promises this value breaks, empty when it keeps them
 */
export function violations(account: AccountDTO | null | undefined): string[] {
    const broken: string[] = [];
    if (account == null) return broken;
    if (account.annualRevenue != null && Number(account.annualRevenue) < 0) {
        broken.push('annualRevenue must be at least 0');
    }
    if (account.employees != null && account.employees < 0) {
        broken.push('employees must be at least 0');
    }
    return broken;
}

/** Whether AccountDTO keeps every promise it makes. */
export function isValid(account: AccountDTO | null | undefined): boolean {
    return violations(account).length === 0;
}
